import{_ as i,o as t,c as a,a2 as r}from"./chunks/framework.BXzK3EA4.js";const h=JSON.parse('{"title":"Version 2.0.0.0 Released","description":"","frontmatter":{},"headers":[],"relativePath":"change-log/release/version-2.0.0.0-released.md","filePath":"change-log/release/version-2.0.0.0-released.md"}'),o={name:"change-log/release/version-2.0.0.0-released.md"};function l(n,e,s,d,c,g){return t(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="version-2-0-0-0-released" tabindex="-1">Version 2.0.0.0 Released <a class="header-anchor" href="#version-2-0-0-0-released" aria-label="Permalink to &quot;Version 2.0.0.0 Released&quot;">​</a></h1><p><strong>Date: 22th Jan 2026</strong></p><h4 id="major-release-complete-frontend-rewrite-feature-expansion" tabindex="-1">Major Release: Complete Frontend Rewrite &amp; Feature Expansion <a class="header-anchor" href="#major-release-complete-frontend-rewrite-feature-expansion" aria-label="Permalink to &quot;Major Release: Complete Frontend Rewrite &amp; Feature Expansion&quot;">​</a></h4><p>This is a major release featuring a complete rewrite of the frontend from Flask/Jinja2 templates to a modern React 19 Single Page Application (SPA). This release includes <strong>212 commits</strong> representing months of development work, introducing new features like Flow Visual Builder, Historify, and enhanced real-time capabilities.</p><hr><h3 id="highlights" tabindex="-1">Highlights <a class="header-anchor" href="#highlights" aria-label="Permalink to &quot;Highlights&quot;">​</a></h3><ul><li><strong>React 19 Frontend</strong> - Complete migration of 77 templates to modern React with TypeScript</li><li><strong>Flow Visual Builder</strong> - Node-based visual workflow builder for trading automation</li><li><strong>Historify</strong> - Historical market data management with DuckDB storage</li><li><strong>Real-Time WebSocket</strong> - Native WebSocket integration for live market data</li><li><strong>Sandbox Mode</strong> - Enhanced sandbox testing environment with sandbox capital</li><li><strong>API Playground</strong> - Bruno-style API testing with WebSocket support</li><li><strong>Python Strategies</strong> - Enhanced scheduler with real-time status and resource limits</li><li><strong>Telegram Bot</strong> - Fixed callbacks and improved status display</li><li><strong>Enhanced Security</strong> - Multiple security improvements and vulnerability fixes</li></ul><hr><h3 id="new-features" tabindex="-1">New Features <a class="header-anchor" href="#new-features" aria-label="Permalink to &quot;New Features&quot;">​</a></h3><h4 id="react-19-frontend-migration-77-templates" tabindex="-1">React 19 Frontend Migration (77 Templates) <a class="header-anchor" href="#react-19-frontend-migration-77-templates" aria-label="Permalink to &quot;React 19 Frontend Migration (77 Templates)&quot;">​</a></h4><p><strong>Phase 1 - Foundation</strong></p><ul><li>Initialized React frontend with Vite, TypeScript, TanStack Query</li><li>Added Flask blueprint to serve React frontend</li><li>Pre-built frontend dist included for community use</li></ul><p><strong>Phase 2 - Core Authentication &amp; Trading</strong></p><ul><li>Login, Dashboard, Profile pages</li><li>Orders, Positions, Holdings pages</li><li>Order placement and management</li></ul><p><strong>Phase 3 - Search &amp; Symbol Management</strong></p><ul><li>FNO Discovery with performance optimization</li><li>Symbol search and watchlist</li><li>Bulk watchlist operations</li></ul><p><strong>Phase 4 - Charts, WebSocket &amp; Sandbox</strong></p><ul><li>TradingView charts integration</li><li>WebSocket Test Console</li><li>Sandbox/Analyzer mode interface</li></ul><p><strong>Phase 5 - Platform Integrations</strong></p><ul><li>TradingView webhook page</li><li>GoCharting integration</li><li>Amibroker integration</li><li>ChartInk integration</li></ul><p><strong>Phase 6 - Strategy &amp; Automation</strong></p><ul><li>Python Strategies management</li><li>Strategy scheduler with SSE</li><li>Strategy logs viewer</li></ul><p><strong>Phase 7 - Monitoring &amp; Administration</strong></p><ul><li>Logs, Latency Monitor, Traffic Logs</li><li>Profile &amp; Security settings</li><li>Action Center for order approval</li><li>Admin &amp; Telegram modules</li></ul><p><strong>Frontend Tech Stack</strong></p><ul><li>React 19 with TypeScript</li><li>Vite 6 build system with code splitting</li><li>TanStack Query v5 for server state</li><li>shadcn/ui + Tailwind CSS 4 + DaisyUI</li><li>Biome.js (replaced ESLint)</li><li>Vitest unit tests + Playwright E2E tests</li><li>Responsive mobile bottom navigation</li><li>Accessibility testing (jest-axe)</li></ul><hr><h4 id="flow-visual-builder" tabindex="-1">Flow Visual Builder <a class="header-anchor" href="#flow-visual-builder" aria-label="Permalink to &quot;Flow Visual Builder&quot;">​</a></h4><ul><li><strong>Node-based visual workflow builder</strong> for trading strategies</li><li><strong>Order Nodes</strong>: Market Order, Limit Order, Smart Order, Basket Order</li><li><strong>Options Order Node</strong>: ATM/ITM/OTM offset resolution for F&amp;O</li><li><strong>Modify Order Node</strong>: Live order management within workflows</li><li><strong>Cancel Order Node</strong>: Cancel single or all orders</li><li><strong>Close Position Node</strong>: Square off positions</li><li><strong>WebSocket Streaming Nodes</strong>: Real-time data within workflows</li><li><strong>Telegram Alert Node</strong>: Send notifications from workflows</li><li><strong>Webhook Integration</strong>: Trigger flows from external systems</li><li><strong>Multi-leg Options Strategy</strong>: Execute complex option strategies</li><li><strong>Keyboard Shortcuts</strong>: Efficient workflow creation</li><li>Service integration for order execution</li></ul><hr><h4 id="historify-historical-data-management" tabindex="-1">Historify - Historical Data Management <a class="header-anchor" href="#historify-historical-data-management" aria-label="Permalink to &quot;Historify - Historical Data Management&quot;">​</a></h4><ul><li><strong>DuckDB-powered storage</strong> for historical market data</li><li><strong>Multi-timeframe support</strong>: 1m, 5m, 15m, 30m, 1h, Daily</li><li><strong>Computed timeframes</strong>: Weekly (W), Monthly (MO), Quarterly (Q), Yearly (Y)</li><li><strong>Aggregation from daily data</strong> for higher timeframes</li><li><strong>Bulk export</strong> with inline symbol selection</li><li><strong>Multi-timeframe export</strong> in single operation</li><li><strong>Parquet import support</strong> for external data sources</li><li><strong>TradingView-style charts</strong> with IST timezone</li><li><strong>Styled crosshair tooltips</strong> with IST timestamps</li><li><strong>Job management</strong>: Pause, resume, cancel operations</li><li><strong>Broker badge display</strong> and theme toggle</li><li><strong>Date selector improvements</strong> with Calendar component</li><li><strong>Exchange market open time alignment</strong> for candle boundaries</li></ul><hr><h4 id="real-time-websocket-integration" tabindex="-1">Real-Time WebSocket Integration <a class="header-anchor" href="#real-time-websocket-integration" aria-label="Permalink to &quot;Real-Time WebSocket Integration&quot;">​</a></h4><ul><li><strong>Native WebSocket</strong> for Holdings and Positions pages</li><li><strong>Unified WebSocket proxy server</strong> on port 8765</li><li><strong>ZeroMQ message bus</strong> for high-performance data distribution (port 5555)</li><li><strong>Connection pooling</strong>: MAX_SYMBOLS_PER_WEBSOCKET (1000) x MAX_WEBSOCKET_CONNECTIONS (3)</li><li><strong>MultiQuotes API fallback</strong> when WebSocket unavailable</li><li><strong>Market timing awareness</strong> for automatic data source switching</li><li><strong>Real-time P&amp;L calculation</strong> using live LTP data</li><li><strong>WebSocket templates</strong> in Playground with Bruno-style collections</li><li><strong>Multi-client subscribe/unsubscribe</strong> support</li><li><strong>Callback-based data retrieval</strong> for Flow nodes</li><li><strong>Pong message display</strong> for manual ping testing</li></ul><hr><h4 id="sandbox-mode-sandbox-testing" tabindex="-1">Sandbox Mode (Sandbox Testing) <a class="header-anchor" href="#sandbox-mode-sandbox-testing" aria-label="Permalink to &quot;Sandbox Mode (Sandbox Testing)&quot;">​</a></h4><ul><li><strong>Isolated sandbox trading</strong> with Rs. 1 Crore sandbox capital</li><li><strong>Realistic margin system</strong> with leverage</li><li><strong>Auto square-off</strong> at exchange timings for F&amp;O contracts</li><li><strong>Complete isolation</strong> from live trading</li><li><strong>Separate database</strong> (sandbox.db) for sandbox trades</li><li><strong>Real-time P&amp;L</strong> using WebSocket data</li><li><strong>Session-based position filtering</strong> for expired contracts</li><li><strong>Expired F&amp;O contract cleanup</strong> on app startup</li><li><strong>Sandbox logs</strong> with date filter and Calendar icons</li><li><strong>Wide dialog display</strong> (98vw) for better visibility</li></ul><hr><h4 id="api-playground" tabindex="-1">API Playground <a class="header-anchor" href="#api-playground" aria-label="Permalink to &quot;API Playground&quot;">​</a></h4><ul><li><strong>Bruno-style API collection browser</strong></li><li><strong>WebSocket testing console</strong> with comprehensive controls</li><li><strong>CodeMirror JSON editor</strong> with syntax highlighting</li><li><strong>Theme support</strong> matching application theme</li><li><strong>Manual ping/pong testing</strong> for WebSocket connections</li><li><strong>Multiple tabs</strong> for endpoints with same path but different names</li><li><strong>Nested braces handling</strong> in body:json parsing</li><li><strong>Source parameter</strong> for History API collections</li></ul><hr><h4 id="python-strategies" tabindex="-1">Python Strategies <a class="header-anchor" href="#python-strategies" aria-label="Permalink to &quot;Python Strategies&quot;">​</a></h4><ul><li><strong>Enhanced scheduler</strong> with mandatory scheduling</li><li><strong>Real-time status updates</strong> via SSE (Server-Sent Events)</li><li><strong>Resource limits</strong> to prevent runaway strategies</li><li><strong>Python Strategy Guide page</strong> with comprehensive help</li><li><strong>FAQ for installing libraries</strong> (TA-Lib, pandas-ta, etc.)</li><li><strong>Log management</strong> with configurable retention</li><li><strong>Reverse chronological logs</strong> with auto-scroll</li><li><strong>Schedule box theme</strong> with opacity-based dark mode colors</li><li><strong>Holiday enforcement</strong> for market-aware scheduling</li><li><strong>Environment Variables feature removed</strong> (security)</li></ul><hr><h4 id="telegram-bot" tabindex="-1">Telegram Bot <a class="header-anchor" href="#telegram-bot" aria-label="Permalink to &quot;Telegram Bot&quot;">​</a></h4><ul><li><strong>Fixed /menu callbacks</strong> for command navigation</li><li><strong>Fixed /status display</strong> for current position status</li><li><strong>Flow Telegram alert integration</strong> using existing send_alert_sync</li><li><strong>Admin &amp; Telegram modules</strong> migrated to React</li></ul><hr><h4 id="email-smtp" tabindex="-1">Email &amp; SMTP <a class="header-anchor" href="#email-smtp" aria-label="Permalink to &quot;Email &amp; SMTP&quot;">​</a></h4><ul><li><strong>Fixed SMTP email delivery</strong></li><li><strong>Updated email templates</strong></li><li><strong>Email icon centering</strong> using table-based layout</li></ul><hr><h4 id="action-center" tabindex="-1">Action Center <a class="header-anchor" href="#action-center" aria-label="Permalink to &quot;Action Center&quot;">​</a></h4><ul><li><strong>Order approval workflow</strong> for managed accounts</li><li><strong>Semi-Auto mode</strong> for manual approval</li><li><strong>Auto mode</strong> for direct execution</li><li><strong>Complete migration</strong> to React interface</li><li><strong>Documentation</strong> added (Module 42)</li></ul><hr><h3 id="improvements" tabindex="-1">Improvements <a class="header-anchor" href="#improvements" aria-label="Permalink to &quot;Improvements&quot;">​</a></h3><h4 id="user-interface" tabindex="-1">User Interface <a class="header-anchor" href="#user-interface" aria-label="Permalink to &quot;User Interface&quot;">​</a></h4><ul><li>Profile menu with mode controls on all pages</li><li>Theme consistency across broker and public pages</li><li>Theme sensitivity for dark/light mode switching</li><li>Broker badge display across pages</li><li>Chart icons in watchlist for smart navigation</li><li>Responsive dialogs with optimized widths</li><li>Mobile bottom navigation</li><li>Accessible icon buttons with aria-labels</li></ul><h4 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h4><ul><li>FNO Discovery performance optimization</li><li>Historify storage optimization</li><li>Code splitting and lazy loading</li><li>Bulk watchlist add optimization</li><li>Connection pooling for WebSocket</li></ul><h4 id="order-management" tabindex="-1">Order Management <a class="header-anchor" href="#order-management" aria-label="Permalink to &quot;Order Management&quot;">​</a></h4><ul><li>P&amp;L % calculation for flat positions using implied investment</li><li>Show dash for P&amp;L % on closed positions</li><li>Preserved realized P&amp;L for closed positions</li><li>Position filtering for session boundaries</li><li>Show closed positions that were traded today</li><li>Expired F&amp;O contract cleanup on startup</li><li>Order field names aligned with Tradeboard schema</li></ul><h4 id="broker-integrations" tabindex="-1">Broker Integrations <a class="header-anchor" href="#broker-integrations" aria-label="Permalink to &quot;Broker Integrations&quot;">​</a></h4><ul><li>AliceBlue holdings symbol field fix</li><li>OAuth broker redirect improvements (AJAX vs browser detection)</li><li>Broker login migrated to React JSON responses</li><li>Updated lot sizes and expiry dates in Bruno collections</li><li>Broker credentials GUI for easy configuration</li></ul><h4 id="charts" tabindex="-1">Charts <a class="header-anchor" href="#charts" aria-label="Permalink to &quot;Charts&quot;">​</a></h4><ul><li>TradingView-style x-axis labels for daily+ timeframes</li><li>IST timezone correction for W/MO/Q/Y timeframes</li><li>Dates instead of time for daily+ timeframes</li><li>CodeMirror JSON editor on TradingView and GoCharting pages</li></ul><hr><h3 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h3><ul><li>Fixed critical frontend vulnerabilities</li><li>Removed environment variables feature from Python strategies</li><li>Added resource limits for strategy execution</li><li>Enhanced CSRF protection</li><li>Security audit documentation added</li><li>Dependency updates for known vulnerabilities</li></ul><hr><h3 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h3><h4 id="user-guide-30-modules" tabindex="-1">User Guide (30 Modules) <a class="header-anchor" href="#user-guide-30-modules" aria-label="Permalink to &quot;User Guide (30 Modules)&quot;">​</a></h4><ul><li>What is Tradeboard, Key Concepts, System Requirements</li><li>Installation Guide, First-Time Setup</li><li>Broker Connection, Dashboard Overview</li><li>Understanding Interface, API Key Management</li><li>Order Types, Smart Orders, Basket Orders</li><li>Positions &amp; Holdings, Analyzer Mode</li><li>Symbol Format Guide</li><li>TradingView, Amibroker, ChartInk, GoCharting Integration</li><li>Python Strategies, Flow Visual Builder</li><li>Action Center, Telegram Bot</li><li>PnL Tracker, Latency Monitor, Traffic Logs</li><li>Security Settings, Two-Factor Authentication</li><li>Troubleshooting, FAQs</li></ul><h4 id="architecture-documentation" tabindex="-1">Architecture Documentation <a class="header-anchor" href="#architecture-documentation" aria-label="Permalink to &quot;Architecture Documentation&quot;">​</a></h4><ul><li>Frontend and Backend Architecture</li><li>Login and Broker Login Flow (Module 03)</li><li>Cache Architecture (Module 04)</li><li>Security Architecture (Module 05)</li><li>WebSockets Architecture (Module 06)</li><li>Sandbox Architecture (Module 07)</li><li>REST API Documentation (Module 09)</li><li>Flow Architecture (Module 10)</li><li>MCP Architecture (Module 41)</li><li>Action Center (Module 42)</li></ul><h4 id="api-documentation" tabindex="-1">API Documentation <a class="header-anchor" href="#api-documentation" aria-label="Permalink to &quot;API Documentation&quot;">​</a></h4><ul><li>All REST endpoints documented</li><li>Tradeboard symbol format reference</li><li>Manual testing guide</li><li>Bruno collections for all APIs</li></ul><h4 id="prd-documents" tabindex="-1">PRD Documents <a class="header-anchor" href="#prd-documents" aria-label="Permalink to &quot;PRD Documents&quot;">​</a></h4><ul><li>Sandbox PRD</li><li>Python Strategies PRD</li><li>Historify PRD</li><li>Broker Factory Design</li><li>WebSocket Guide</li><li>Latency Audit</li></ul><h4 id="other-documentation" tabindex="-1">Other Documentation <a class="header-anchor" href="#other-documentation" aria-label="Permalink to &quot;Other Documentation&quot;">​</a></h4><ul><li>Why Build with Tradeboard guide</li><li>Ubuntu Server deployment</li><li>Docker deployment guide</li><li>Security Policy</li><li>Contributor guidelines for /frontend/dist</li></ul><hr><h3 id="infrastructure" tabindex="-1">Infrastructure <a class="header-anchor" href="#infrastructure" aria-label="Permalink to &quot;Infrastructure&quot;">​</a></h3><h4 id="database-architecture-5-databases" tabindex="-1">Database Architecture (5 Databases) <a class="header-anchor" href="#database-architecture-5-databases" aria-label="Permalink to &quot;Database Architecture (5 Databases)&quot;">​</a></h4><ul><li><code>db/tradeboard.db</code> - Main database (users, orders, settings)</li><li><code>db/logs.db</code> - Traffic and API logs</li><li><code>db/latency.db</code> - Latency monitoring data</li><li><code>db/sandbox.db</code> - Analyzer/sandbox mode (isolated)</li><li><code>db/historify.duckdb</code> - Historical market data (DuckDB)</li></ul><h4 id="server-configuration" tabindex="-1">Server Configuration <a class="header-anchor" href="#server-configuration" aria-label="Permalink to &quot;Server Configuration&quot;">​</a></h4><ul><li>React frontend served via Flask blueprint</li><li>Pre-built frontend dist for community use</li><li>System permissions monitoring for db directories</li><li>Ngrok ERR_NGROK_108 fix in debug mode</li><li>Prevented duplicate startup messages</li><li>Password reset fixed for React migration</li><li>Startup log noise reduced (DEBUG level)</li></ul><h4 id="docker" tabindex="-1">Docker <a class="header-anchor" href="#docker" aria-label="Permalink to &quot;Docker&quot;">​</a></h4><ul><li>Updated .dockerignore for React frontend</li><li>Added db directory to permission commands</li><li>Frontend documentation included</li></ul><hr><h3 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h3><h4 id="python" tabindex="-1">Python <a class="header-anchor" href="#python" aria-label="Permalink to &quot;Python&quot;">​</a></h4><ul><li>DuckDB 1.4.3</li><li>PyArrow 22.0.0</li><li>FastParquet 2025.12.0</li><li>simple-websocket 1.1.0</li><li>Python 3.12+ required</li></ul><h4 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h4><ul><li>React 19</li><li>TypeScript 5.6</li><li>Vite 6</li><li>TanStack Query v5</li><li>shadcn/ui components</li><li>Tailwind CSS 4 + DaisyUI</li><li>Biome.js</li><li>Vitest + Playwright</li><li>CodeMirror 6</li><li>Socket.IO Client</li></ul><hr><h3 id="breaking-changes" tabindex="-1">Breaking Changes <a class="header-anchor" href="#breaking-changes" aria-label="Permalink to &quot;Breaking Changes&quot;">​</a></h3><ul><li>Frontend routes served from React SPA</li><li>Old Jinja2 templates removed completely</li><li>Static folder cleaned up (React has all assets)</li><li>API responses updated for React JSON format</li><li>Broker login returns JSON instead of HTML redirects</li><li>Environment variables feature removed from Python strategies</li></ul><hr><h3 id="migration-guide" tabindex="-1">Migration Guide <a class="header-anchor" href="#migration-guide" aria-label="Permalink to &quot;Migration Guide&quot;">​</a></h3><p>For users upgrading from v1.0.0.41:</p><ol><li><p><strong>Backup your data</strong></p><ul><li>Export databases before upgrading</li><li>Backup .env configuration</li></ul></li><li><p><strong>Update environment</strong></p><ul><li>Python 3.12+ required</li><li>Node.js 20+ for frontend development</li></ul></li><li><p><strong>Install dependencies</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                    # Python dependencies</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Frontend (for development only)</span></span></code></pre></div></li><li><p><strong>Database migration</strong></p><ul><li>Existing databases are compatible</li><li>New sandbox.db created automatically</li><li>New historify.duckdb created automatically</li></ul></li><li><p><strong>Clear browser cache</strong></p><ul><li>React frontend requires fresh load</li><li>Clear all cookies and cache for the domain</li></ul></li><li><p><strong>Review breaking changes</strong></p><ul><li>Update any custom integrations using old template routes</li><li>Update broker login handling if using custom flows</li></ul></li></ol><hr><h3 id="contributors" tabindex="-1">Contributors <a class="header-anchor" href="#contributors" aria-label="Permalink to &quot;Contributors&quot;">​</a></h3><p>Special thanks to all contributors who made this release possible:</p><ul><li>@Kalaiviswa - Flow Visual Builder, React migration</li><li>@akhandhediya - WebSocket Playground</li><li>Community contributors and testers (Deepanshu and Roch Ronaldo)</li></ul><hr><h3 id="previous-releases" tabindex="-1">Previous Releases <a class="header-anchor" href="#previous-releases" aria-label="Permalink to &quot;Previous Releases&quot;">​</a></h3><h4 id="_1-0-0-41-and-earlier" tabindex="-1">[1.0.0.41] and earlier <a class="header-anchor" href="#_1-0-0-41-and-earlier" aria-label="Permalink to &quot;\\[1.0.0.41] and earlier&quot;">​</a></h4><p>See <a href="https://github.com/wesoftcorp/tradeboard-docs/releases" target="_blank" rel="noreferrer">GitHub Releases</a> for previous version history.</p><hr><h3 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h3><ul><li><strong>Repository</strong>: <a href="https://github.com/wesoftcorp/tradeboard-docs" target="_blank" rel="noreferrer">https://github.com/wesoftcorp/tradeboard-docs</a></li><li><strong>Documentation</strong>: <a href="https://docs.algo.wesoftcorp.com" target="_blank" rel="noreferrer">https://docs.algo.wesoftcorp.com</a></li><li><strong>Discord</strong>: <a href="https://www.tradeboard.in/discord" target="_blank" rel="noreferrer">https://www.tradeboard.in/discord</a></li></ul><hr>`,113)])])}const m=i(o,[["render",l]]);export{h as __pageData,m as default};
